	(64,64,1,NULL,'__temp_etssgfgmmofjurapxtfmkrpoyidaadyzacxs',NULL,'{\"54e0155b-2027-4647-9f61-6a820c7b699d\": \"splitSection\"}',1,'2026-03-28 23:21:47','2026-03-28 23:21:47','031392cb-e033-475d-95a5-a973ab5b14f9'),
	(67,67,1,NULL,NULL,NULL,'{\"0b92e79b-252c-4fdd-9467-b23f1b66911f\": [], \"4c037aa7-7177-41fc-84d2-94d8e8aac99d\": false, \"4d44aae0-e56d-4315-bfaa-83937eb0421d\": \"Our story\", \"5fd7f09f-bfc0-43e2-a982-7242517a38df\": \"Est. in Charlotte, NC\", \"83858805-a6cd-43b6-9279-0edcf7240fb8\": \"<p>Charlie\'s Barkery started with one dog, one kitchen, and a whole lot of peanut butter. What began as a hobby turned into a mission — giving dogs the same care and quality ingredients we\'d want for ourselves.<br /> </p><p>Every treat is handmade in small batches using dog-safe, wholesome ingredients. No fillers, no funny stuff — just good food for good dogs.</p>\", \"a65ee03d-5758-4410-8604-5324d9775b1e\": true, \"b1fc4697-c4a0-457e-be69-38665a393900\": \"white\", \"f075b188-d366-4033-b4ba-472195410663\": \"Baked with Love, Made for Dogs\", \"fa3aa4f4-0531-4405-be51-1ae540e06fb0\": false}',1,'2026-03-28 23:22:37','2026-05-12 03:13:37','76a6f393-3c93-40cc-9df3-9f99d2f564bf'),
	(139,139,1,NULL,'__temp_etssgfgmmofjurapxtfmkrpoyidaadyzacxs',NULL,'{\"54e0155b-2027-4647-9f61-6a820c7b699d\": \"splitSection\"}',1,'2026-04-03 18:02:34','2026-04-03 18:02:34','5c4e27c8-5e7b-4061-afcb-12b2cc2d8da9'),
	(140,140,1,NULL,NULL,NULL,'{\"4c037aa7-7177-41fc-84d2-94d8e8aac99d\": false, \"4d44aae0-e56d-4315-bfaa-83937eb0421d\": \"Our story\", \"5fd7f09f-bfc0-43e2-a982-7242517a38df\": \"Est. in Charlotte, NC\", \"83858805-a6cd-43b6-9279-0edcf7240fb8\": \"<p>Lorem ipsum dolor sit amet, consectetur adipisicing elit. Aliquid aperiam, deleniti dolores eaque illum in iure modi nihil nobis officia perferendis quas quia quibusdam quis quod saepe ullam voluptas voluptatem.</p>\", \"a3c25b1b-0d05-48dc-85f4-25c8f848c54a\": false, \"a65ee03d-5758-4410-8604-5324d9775b1e\": true, \"f075b188-d366-4033-b4ba-472195410663\": \"Baked with Love, Made for Dogs\", \"f531efbe-8694-4e7e-9973-ec72a83577b3\": false, \"fa3aa4f4-0531-4405-be51-1ae540e06fb0\": false}',1,'2026-04-03 18:02:34','2026-04-03 18:02:34','229211b2-6fc6-40bd-a534-a2fa578db3a8'),
	(144,144,1,NULL,'__temp_hhzrcvazyquagjeirsxdtpoymjuamcjdoznk',NULL,'{\"54e0155b-2027-4647-9f61-6a820c7b699d\": \"splitSection\"}',1,'2026-04-03 18:02:52','2026-04-03 18:02:52','e2757675-f287-4ab7-98ac-42088132e98e'),
	(145,145,1,NULL,NULL,NULL,'{\"0b92e79b-252c-4fdd-9467-b23f1b66911f\": [], \"4c037aa7-7177-41fc-84d2-94d8e8aac99d\": true, \"4d44aae0-e56d-4315-bfaa-83937eb0421d\": \"make it special\", \"5fd7f09f-bfc0-43e2-a982-7242517a38df\": \"Order 48 hrs in advance\", \"83858805-a6cd-43b6-9279-0edcf7240fb8\": \"<p>Because every pup deserves a moment. Our dog-safe birthday cakes are handmade to order — customizable, frosted, and ready to make tails wag.</p><p> </p><ul style=\\\"list-style-type:disc;\\\"><li>100% dog-safe ingredients</li><li>Made to order — customizable message</li><li>Available for pickup or shipping</li></ul>\", \"a65ee03d-5758-4410-8604-5324d9775b1e\": true, \"a9fd0a03-657f-4952-9c55-566045985717\": \"So we have time to bake it fresh, just for your pup.\", \"b1fc4697-c4a0-457e-be69-38665a393900\": \"charcoal\", \"f075b188-d366-4033-b4ba-472195410663\": \"Brithday Cakes for very Good dogs\", \"fa3aa4f4-0531-4405-be51-1ae540e06fb0\": true}',1,'2026-04-03 18:02:52','2026-05-12 03:13:37','1d013ea1-9851-49fd-9d1c-f0022257363f'),
