	(471,471,1,NULL,NULL,NULL,NULL,1,'2026-05-12 03:13:37','2026-05-12 03:13:37','c0668d61-1d88-4dac-86eb-df22684f818c'),
	(472,472,1,NULL,NULL,NULL,'{\"4c037aa7-7177-41fc-84d2-94d8e8aac99d\": true, \"4d44aae0-e56d-4315-bfaa-83937eb0421d\": \"make it special\", \"5fd7f09f-bfc0-43e2-a982-7242517a38df\": \"Order 48 hrs in advance\", \"83858805-a6cd-43b6-9279-0edcf7240fb8\": \"<p>Because every pup deserves a moment. Our dog-safe birthday cakes are handmade to order — customizable, frosted, and ready to make tails wag.</p><p> </p><ul style=\\\"list-style-type:disc;\\\"><li>100% dog-safe ingredients</li><li>Made to order — customizable message</li><li>Available for pickup or shipping</li></ul>\", \"a65ee03d-5758-4410-8604-5324d9775b1e\": true, \"a9fd0a03-657f-4952-9c55-566045985717\": \"So we have time to bake it fresh, just for your pup.\", \"b1fc4697-c4a0-457e-be69-38665a393900\": \"charcoal\", \"f075b188-d366-4033-b4ba-472195410663\": \"Brithday Cakes for very Good dogs\", \"fa3aa4f4-0531-4405-be51-1ae540e06fb0\": true}',1,'2026-05-12 03:13:37','2026-05-12 03:13:37','0bec2dd1-d8ce-47f3-bbd9-38c062381d4b'),
