	(477,477,1,NULL,NULL,NULL,NULL,1,'2026-05-12 03:13:37','2026-05-12 03:13:37','7d72a5e3-54f5-4cb3-9e0f-1ce3d13fab88'),
	(478,478,1,NULL,NULL,NULL,'{\"4c037aa7-7177-41fc-84d2-94d8e8aac99d\": false, \"4d44aae0-e56d-4315-bfaa-83937eb0421d\": \"Our story\", \"5fd7f09f-bfc0-43e2-a982-7242517a38df\": \"Est. in Charlotte, NC\", \"83858805-a6cd-43b6-9279-0edcf7240fb8\": \"<p>Charlie\'s Barkery started with one dog, one kitchen, and a whole lot of peanut butter. What began as a hobby turned into a mission — giving dogs the same care and quality ingredients we\'d want for ourselves.<br /> </p><p>Every treat is handmade in small batches using dog-safe, wholesome ingredients. No fillers, no funny stuff — just good food for good dogs.</p>\", \"a65ee03d-5758-4410-8604-5324d9775b1e\": true, \"b1fc4697-c4a0-457e-be69-38665a393900\": \"white\", \"f075b188-d366-4033-b4ba-472195410663\": \"Baked with Love, Made for Dogs\", \"fa3aa4f4-0531-4405-be51-1ae540e06fb0\": false}',1,'2026-05-12 03:13:37','2026-05-12 03:13:37','d9f479dd-692f-47fe-bd27-822a1fe2b311'),
